class BenefitLimitScope(str, Enum):
    TRANSACTION = "TRANSACTION"
    DAY = "DAY"
    CONTRACT_PERIOD = "CONTRACT_PERIOD"
    COMPANY = "COMPANY"
    UNIT = "UNIT"


class BenefitStackingMode(str, Enum):
    STACKABLE = "STACKABLE"
    EXCLUSIVE = "EXCLUSIVE"
    SAME_POLICY_ONLY = "SAME_POLICY_ONLY"


@dataclass(frozen=True)
class BenefitLimitPolicy:
    policy_id: str
    policy_version: str
    scope: BenefitLimitScope
    monetary_cap: Optional[float] = None
    usage_count_cap: Optional[int] = None
    stacking_mode: BenefitStackingMode = BenefitStackingMode.EXCLUSIVE


@dataclass(frozen=True)
class BenefitUsageSnapshot:
    confirmed_net_amount: float
    confirmed_usage_count: int
    active_promotion_ids: tuple[str, ...] = ()
    active_policy_ids: tuple[str, ...] = ()


@dataclass(frozen=True)
class BenefitLimitDecision:
    allowed: bool
    remaining_amount: Optional[float]
    remaining_uses: Optional[int]
    reasons: tuple[str, ...]


def evaluate_benefit_limits(
    *,
    policy: BenefitLimitPolicy,
    snapshot: BenefitUsageSnapshot,
    requested_amount: float,
    current_promotion_id: Optional[str] = None,
) -> BenefitLimitDecision:
    if not str(policy.policy_id or "").strip() or not str(policy.policy_version or "").strip():
        raise ValueError("BenefitLimitPolicy requiere policy_id y policy_version")
    if requested_amount < 0:
        raise ValueError("requested_amount no puede ser negativo")
    if snapshot.confirmed_net_amount < 0 or snapshot.confirmed_usage_count < 0:
        raise ValueError("El acumulado confirmado no puede ser negativo")
    reasons = []
    remaining_amount = None
    remaining_uses = None
    if policy.monetary_cap is not None:
        if policy.monetary_cap < 0:
            raise ValueError("monetary_cap no puede ser negativo")
        remaining_amount = round(max(0.0, policy.monetary_cap - snapshot.confirmed_net_amount), 2)
        if requested_amount > remaining_amount:
            reasons.append("MONETARY_CAP_EXCEEDED")
    if policy.usage_count_cap is not None:
        if policy.usage_count_cap < 0:
            raise ValueError("usage_count_cap no puede ser negativo")
        remaining_uses = max(0, policy.usage_count_cap - snapshot.confirmed_usage_count)
        if remaining_uses <= 0:
            reasons.append("USAGE_COUNT_CAP_EXCEEDED")
    if policy.stacking_mode == BenefitStackingMode.EXCLUSIVE and snapshot.active_promotion_ids:
        reasons.append("OTHER_PROMOTION_ACTIVE")
    if policy.stacking_mode == BenefitStackingMode.SAME_POLICY_ONLY:
        incompatible = [pid for pid in snapshot.active_policy_ids if pid != policy.policy_id]
        if incompatible:
            reasons.append("INCOMPATIBLE_POLICY_STACK")
    return BenefitLimitDecision(
        allowed=not reasons,
        remaining_amount=remaining_amount,
        remaining_uses=remaining_uses,
        reasons=tuple(reasons),
    )
